begin;
do $catalog$
declare current_doc jsonb; services jsonb; new_service jsonb; quantities jsonb; point jsonb; budget numeric; lo integer; hi integer; ratio numeric;
 budgets integer[]:=array[1000,3000,5000,10000,20000,35000,50000,75000,100000];
begin
 select document into current_doc from public.nc_offer_catalog where id=1 for update;
 if current_doc is null then raise exception 'Leistungskatalog fehlt.'; end if;
 services:=current_doc->'services';
 for new_service in select value from jsonb_array_elements('[{"id": "responsive", "group": "Website & Inhalte", "label": "Responsive Darstellung", "unit": "Einrichtung", "description": "Optimierung der vereinbarten Seitentypen für Smartphone, Tablet und Desktop.", "quantities": [1, 1, 1, 1, 1, 1, 1, 1, 1]}, {"id": "consent", "group": "Website & Inhalte", "label": "Cookie- & Einwilligungsverwaltung", "unit": "Einrichtung", "description": "Technische Einbindung passend zu den eingesetzten Diensten. Anbietergebühren separat.", "quantities": [1, 1, 1, 1, 1, 1, 1, 1, 1]}, {"id": "redirects", "group": "Website & Inhalte", "label": "Weiterleitungen bestehender URLs", "unit": "Weiterleitungen", "description": "Übernahme abgestimmter alter URLs beim Relaunch.", "quantities": [0, 3, 5, 10, 20, 30, 50, 80, 120]}, {"id": "content_collections", "group": "Website & Inhalte", "label": "Redaktionelle Inhaltsbereiche", "unit": "Bereiche", "description": "Zum Beispiel Blog, Team, Referenzen oder Wissensbereich mit bearbeitbaren Inhalten.", "quantities": [0, 0, 1, 2, 4, 6, 10, 16, 24]}, {"id": "search", "group": "Website & Inhalte", "label": "Suche & Filter", "unit": "Suchbereiche", "description": "Abgestimmte Such- oder Filteransichten für Inhalte und Datensätze.", "quantities": [0, 0, 0, 1, 1, 2, 3, 4, 5]}, {"id": "booking", "group": "Backend & Portale", "label": "Termin- & Buchungsabläufe", "unit": "Abläufe", "description": "Je Ablauf ein abgestimmter Buchungsprozess einschließlich Bestätigung.", "quantities": [0, 0, 0, 1, 2, 3, 4, 6, 8]}, {"id": "pipelines", "group": "Backend & Portale", "label": "Vertriebs- & Bearbeitungsstrecken", "unit": "Strecken", "description": "Definierte Statusfolgen für Interessenten, Kunden oder Aufträge.", "quantities": [0, 0, 0, 1, 2, 4, 6, 8, 12]}, {"id": "dashboards", "group": "Backend & Portale", "label": "Kennzahlen-Dashboards", "unit": "Ansichten", "description": "Abgestimmte Übersichten mit Kennzahlen aus den angeschlossenen Daten.", "quantities": [0, 0, 0, 1, 2, 3, 5, 8, 12]}, {"id": "approvals", "group": "Backend & Portale", "label": "Freigabeprozesse", "unit": "Prozesse", "description": "Zuständigkeiten und Freigaben für Dokumente, Aufgaben oder interne Vorgänge.", "quantities": [0, 0, 0, 1, 2, 3, 5, 8, 12]}, {"id": "finance_exports", "group": "Finance & Abrechnung", "label": "Buchhaltungs- & Datenexporte", "unit": "Exportformate", "description": "Abgestimmte Formate zur Übergabe von Rechnungs- oder Geschäftsdaten.", "quantities": [0, 0, 0, 0, 1, 2, 3, 4, 6]}, {"id": "payment_flows", "group": "Finance & Abrechnung", "label": "Zahlungsanbindungen", "unit": "Anbindungen", "description": "Technische Anbindung eines abgestimmten Zahlungsablaufs; Transaktionsgebühren separat.", "quantities": [0, 0, 0, 0, 1, 2, 3, 4, 5]}, {"id": "invoice_templates", "group": "Finance & Abrechnung", "label": "Angebots- & Rechnungsvorlagen", "unit": "Vorlagen", "description": "Gestaltete Belegvorlagen mit abgestimmten Feldern und Nummernkreisen.", "quantities": [0, 0, 0, 0, 2, 3, 4, 6, 8]}, {"id": "finance_roles", "group": "Finance & Abrechnung", "label": "Freigaben im Finance-Portal", "unit": "Abläufe", "description": "Abgestimmte Rollen und Prüfabläufe für Belege und Abrechnung.", "quantities": [0, 0, 0, 0, 1, 2, 3, 4, 6]}, {"id": "notifications", "group": "Automatisierung & KI", "label": "E-Mail- & Systembenachrichtigungen", "unit": "Vorlagen", "description": "Abgestimmte Auslöser und Textvorlagen. Versand- und Anbietergebühren separat.", "quantities": [0, 0, 1, 3, 6, 10, 15, 20, 30]}, {"id": "ai_sources", "group": "Automatisierung & KI", "label": "Wissensquellen für KI-Agenten", "unit": "Quellen", "description": "Definierte Dokumentensammlungen oder Datenquellen. Umfang und Aktualisierung werden abgestimmt.", "quantities": [0, 0, 0, 1, 3, 5, 10, 20, 30]}, {"id": "handover", "group": "Zusammenarbeit & Qualität", "label": "Einweisung & Übergabe", "unit": "Termine", "description": "Je Termin bis zu 45 Minuten Einweisung zu den vereinbarten Systemen.", "quantities": [1, 1, 1, 2, 3, 4, 5, 8, 10]}, {"id": "accessibility", "group": "Zusammenarbeit & Qualität", "label": "Prüfung der Bedienbarkeit", "unit": "Prüfdurchläufe", "description": "Tastaturbedienung, Kontraste und Formularbeschriftungen im vereinbarten Umfang.", "quantities": [1, 1, 1, 2, 2, 3, 3, 4, 5]}, {"id": "performance", "group": "Zusammenarbeit & Qualität", "label": "Ladezeit- & Darstellungschecks", "unit": "Prüfdurchläufe", "description": "Kontrolle und Optimierung der vereinbarten Seiten und Hauptabläufe.", "quantities": [1, 1, 1, 2, 2, 3, 3, 4, 5]}, {"id": "care_reports", "group": "Monatliche Betreuung", "label": "Betreuungs- & Leistungsauszüge", "unit": "Auszüge", "description": "Übersicht der dokumentierten Arbeiten und verbrauchten Zeitkontingente pro Monat.", "quantities": [1, 1, 1, 1, 1, 1, 1, 1, 1]}, {"id": "care_reviews", "group": "Monatliche Betreuung", "label": "Entwicklungsgespräche pro Monat", "unit": "Termine", "description": "Je Termin bis zu 30 Minuten; auf das monatliche Zeitkontingent angerechnet.", "quantities": [0, 0, 0, 1, 1, 2, 2, 3, 4]}]'::jsonb) loop
  if not exists(select 1 from jsonb_array_elements(services) s where s->>'id'=new_service->>'id') then
   quantities:='[]'::jsonb;
   for point in select value from jsonb_array_elements(current_doc->'points') loop
    budget:=(point->>'budget')::numeric;hi:=1;
    while hi<array_length(budgets,1) and budgets[hi]<budget loop hi:=hi+1;end loop;
    lo:=greatest(1,hi-1);ratio:=case when lo=hi then 0 else (budget-budgets[lo])/(budgets[hi]-budgets[lo]) end;
    quantities:=quantities||jsonb_build_array(floor((new_service->'quantities'->>(lo-1))::numeric+((new_service->'quantities'->>(hi-1))::numeric-(new_service->'quantities'->>(lo-1))::numeric)*ratio));
   end loop;
   services:=services||jsonb_build_array(jsonb_set(new_service,'{quantities}',quantities));
  end if;
 end loop;
 update public.nc_offer_catalog set version=version+1,document=jsonb_set(jsonb_set(jsonb_set(current_doc,'{services}',services),'{monthlyPricing}','"commercial"'::jsonb),'{version}',to_jsonb(version+1)),updated_at=now() where id=1;
end $catalog$;
notify pgrst, 'reload schema';
commit;
